"""Domain models. All monetary amounts are integer cents.

Sign convention: a debit is a positive amount, a credit is a negative amount.
A well-formed transaction's entries sum to exactly zero.
"""


class Account:
    def __init__(self, code, name, kind="asset"):
        self.code = code
        self.name = name
        self.kind = kind  # asset | liability | equity | income | expense

    def __repr__(self):
        return "Account(%r, %r)" % (self.code, self.name)


class Entry:
    """One leg of a transaction: a signed integer-cent amount against an account."""

    def __init__(self, account_code, amount_cents):
        self.account_code = account_code
        self.amount_cents = int(amount_cents)

    def __repr__(self):
        return "Entry(%r, %d)" % (self.account_code, self.amount_cents)


class Transaction:
    def __init__(self, txn_id, date, entries, memo=""):
        self.txn_id = txn_id
        self.date = date  # ISO "YYYY-MM-DD" string
        self.entries = list(entries)
        self.memo = memo

    def __repr__(self):
        return "Transaction(%r, %s, %d entries)" % (self.txn_id, self.date, len(self.entries))

"""Validation and posting of transactions into an in-memory journal."""


class PostingError(Exception):
    pass


def is_balanced(txn):
    """A transaction is balanced iff its entry amounts sum to exactly zero."""
    total = 0
    for e in txn.entries:
        total += e.amount_cents
    return total == 0


def post_transaction(journal, txn, known_accounts):
    """Append `txn` to `journal` after validating it.

    Rules:
      - the transaction must reference at least two entries,
      - every entry's account must be a known account code,
      - the transaction must be balanced (entries sum to zero).
    Returns the journal (mutated in place).
    """
    if len(txn.entries) < 2:
        raise PostingError("transaction %r needs at least two entries" % txn.txn_id)
    for e in txn.entries:
        if e.account_code not in known_accounts:
            raise PostingError("unknown account %r" % e.account_code)
    if not is_balanced(txn):
        raise PostingError("transaction %r does not balance" % txn.txn_id)
    journal.append(txn)
    return journal

"""Aggregate account balances from a posted journal."""


def account_balance(journal, account_code):
    """Sum every entry in the journal that touches `account_code`.

    Returns integer cents (positive = net debit, negative = net credit).
    """
    total = 0
    for txn in journal:
        for e in txn.entries:
            if e.account_code == account_code:
                total += e.amount_cents
    return total


def all_balances(journal):
    """Return {account_code: balance_cents} across the whole journal."""
    balances = {}
    for txn in journal:
        for e in txn.entries:
            balances[e.account_code] = balances.get(e.account_code, 0) + e.amount_cents
    return balances
